import type {ChatSetPeerOptions} from '@lib/appImManager';

// * https://core.telegram.org/api/links

export enum INTERNAL_LINK_TYPE {
  MESSAGE,
  PRIVATE_POST,
  STICKER_SET,
  JOIN_CHAT,
  VOICE_CHAT,
  USER_PHONE_NUMBER,
  INVOICE,
  EMOJI_SET,
  ATTACH_MENU_BOT,
  WEB_APP,
  ADD_LIST,
  STORY,
  BOOST,
  PREMIUM_FEATURES,
  GIFT_CODE,
  BUSINESS_CHAT,
  STARS_TOPUP,
  SHARE,
  UNIQUE_STAR_GIFT,
  STAR_GIFT_COLLECTION,
  STORY_ALBUM,
  INSTANT_VIEW,
  NEW,
  SETTINGS,
  CONTACTS,
  CHATS,
  CONFERENCE_CALL,
  ADD_AI_STYLE,
  CONTACT_TOKEN,
  WALLET_SEND,
  TON_CONNECT
};

export type InternalLink =
  InternalLink.InternalLinkMessage |
  InternalLink.InternalLinkPrivatePost |
  InternalLink.InternalLinkStickerSet |
  InternalLink.InternalLinkJoinChat |
  InternalLink.InternalLinkVoiceChat |
  InternalLink.InternalLinkUserPhoneNumber |
  InternalLink.InternalLinkInvoice |
  InternalLink.InternalLinkEmojiSet |
  InternalLink.InternalLinkAttachMenuBot |
  InternalLink.InternalLinkWebApp |
  InternalLink.InternalLinkAddList |
  InternalLink.InternalLinkStory |
  InternalLink.InternalLinkBoost |
  InternalLink.InternalLinkPremiumFeatures |
  InternalLink.InternalLinkGiftCode |
  InternalLink.InternalLinkBusinessChat |
  InternalLink.InternalLinkStarsTopup |
  InternalLink.InternalLinkShare |
  InternalLink.InternalLinkUniqueStarGift |
  InternalLink.InternalLinkStarGiftCollection |
  InternalLink.InternalLinkStoryAlbum |
  InternalLink.InternalLinkInstantView |
  InternalLink.InternalLinkNew |
  InternalLink.InternalLinkSettings |
  InternalLink.InternalLinkContacts |
  InternalLink.InternalLinkChats |
  InternalLink.InternalLinkConferenceCall |
  InternalLink.InternalLinkAddAiStyle |
  InternalLink.InternalLinkContactToken |
  InternalLink.InternalLinkWalletSend |
  InternalLink.InternalLinkTonConnect;

export namespace InternalLink {
  export interface InternalLinkMessage {
    _: INTERNAL_LINK_TYPE.MESSAGE,
    domain: string,
    post?: string,
    comment?: string,
    thread?: string,
    start?: string,
    startgroup?: string,
    startchannel?: string,
    admin?: string,
    option?: string,
    t?: string, // media timestamp
    single?: string, // present (empty) when the link is to this one item of an album, not to the whole album
    text?: string,
    game?: string, // a bot's game, by its short name, to share to a chat
    free?: string, // a code that removes the owner's message fee for the one who follows the link
    stack?: ChatSetPeerOptions['stack'] // local
  }

  export interface InternalLinkPrivatePost {
    _: INTERNAL_LINK_TYPE.PRIVATE_POST,
    channel: string,
    post: string,
    thread?: string,
    comment?: string,
    option?: string,
    t?: string // media timestamp
    single?: string, // see InternalLinkMessage
    stack?: ChatSetPeerOptions['stack'] // local
  }

  export interface InternalLinkStickerSet {
    _: INTERNAL_LINK_TYPE.STICKER_SET,
    set: string
  }

  export interface InternalLinkJoinChat {
    _: INTERNAL_LINK_TYPE.JOIN_CHAT,
    invite: string
  }

  export interface InternalLinkVoiceChat {
    _: INTERNAL_LINK_TYPE.VOICE_CHAT,
    id?: string,
    access_hash?: string,
    chat_id?: string,
    domain?: string,
    livestream?: string,
    videochat?: string,
    voicechat?: string
  }

  export interface InternalLinkUserPhoneNumber {
    _: INTERNAL_LINK_TYPE.USER_PHONE_NUMBER,
    phone: string,
    text?: string,
    free?: string // a code that removes the owner's message fee for the one who follows the link
  }

  export interface InternalLinkInvoice {
    _: INTERNAL_LINK_TYPE.INVOICE,
    slug: string
  }

  export interface InternalLinkEmojiSet {
    _: INTERNAL_LINK_TYPE.EMOJI_SET,
    set: string
  }

  export interface InternalLinkAttachMenuBot {
    _: INTERNAL_LINK_TYPE.ATTACH_MENU_BOT,
    startattach?: string,
    choose?: TelegramChoosePeerType,
    attach?: string,
    domain?: string,
    nestedLink?: InternalLink
  }

  export interface InternalLinkWebApp {
    _: INTERNAL_LINK_TYPE.WEB_APP,
    domain: string,
    appname: string,
    startapp?: string,
    masked?: boolean,
    mode?: 'compact' | 'fullscreen'
  }

  export interface InternalLinkAddList {
    _: INTERNAL_LINK_TYPE.ADD_LIST,
    slug: string
  }

  export interface InternalLinkStory {
    _: INTERNAL_LINK_TYPE.STORY,
    domain: string,
    story: string
  }

  export interface InternalLinkBoost {
    _: INTERNAL_LINK_TYPE.BOOST,
    domain?: string,
    channel?: string
  }

  export interface InternalLinkPremiumFeatures {
    _: INTERNAL_LINK_TYPE.PREMIUM_FEATURES,
    ref?: string
  }

  export interface InternalLinkGiftCode {
    _: INTERNAL_LINK_TYPE.GIFT_CODE,
    slug: string,
    stack?: ChatSetPeerOptions['stack'] // local
  }

  export interface InternalLinkBusinessChat {
    _: INTERNAL_LINK_TYPE.BUSINESS_CHAT,
    slug: string
  }

  /**
   * `t.me/sendgrams?to=@user|address&amount=…&text=…` or `ton://transfer/<address>?amount=&text=&exp=`
   */
  export interface InternalLinkWalletSend {
    _: INTERNAL_LINK_TYPE.WALLET_SEND,
    to?: string,
    /** Grams as a decimal */
    amount?: string,
    text?: string,
    /** the comment goes encrypted: `1` / `true` */
    encrypted?: string,
    /** the whole `ton://transfer` link, parsed by the wallet engine */
    tonLink?: string
  }

  /**
   * A TON Connect link (`tc://`, `tg://ton-connect`, `t.me/sendgrams?startapp=tonconnect-…`): a dApp connecting to the
   * wallet, or waking it up for a request it sent
   */
  export interface InternalLinkTonConnect {
    _: INTERNAL_LINK_TYPE.TON_CONNECT,
    url: string
  }

  export interface InternalLinkStarsTopup {
    _: INTERNAL_LINK_TYPE.STARS_TOPUP,
    balance: string,
    purpose: string
  }

  export interface InternalLinkShare {
    _: INTERNAL_LINK_TYPE.SHARE,
    url?: string,
    text?: string
  }

  export interface InternalLinkUniqueStarGift {
    _: INTERNAL_LINK_TYPE.UNIQUE_STAR_GIFT,
    slug: string
  }

  export interface InternalLinkStarGiftCollection {
    _: INTERNAL_LINK_TYPE.STAR_GIFT_COLLECTION,
    domain: string,
    id: string
  }

  export interface InternalLinkStoryAlbum {
    _: INTERNAL_LINK_TYPE.STORY_ALBUM,
    domain: string,
    id: string
  }

  export interface InternalLinkInstantView {
    _: INTERNAL_LINK_TYPE.INSTANT_VIEW,
    url: string
  }

  export interface InternalLinkNew {
    _: INTERNAL_LINK_TYPE.NEW,
    type?: 'group' | 'contact' | 'channel'
  }

  export interface InternalLinkSettings {
    _: INTERNAL_LINK_TYPE.SETTINGS,
    path: string
  }

  export interface InternalLinkContacts {
    _: INTERNAL_LINK_TYPE.CONTACTS,
    type?: 'search' | 'sort' | 'new' | 'invite' | 'manage'
  }

  export interface InternalLinkChats {
    _: INTERNAL_LINK_TYPE.CHATS,
    type?: 'search' | 'emoji-status'
  }

  // t.me/call/<slug> and tg://call?slug=<slug> — invite link for a
  // TdE2E-encrypted conference call. The slug resolves to an
  // `inputGroupCallSlug` that we feed straight into
  // `groupCallsController.joinConference`.
  export interface InternalLinkConferenceCall {
    _: INTERNAL_LINK_TYPE.CONFERENCE_CALL,
    slug: string
  }

  export interface InternalLinkAddAiStyle {
    _: INTERNAL_LINK_TYPE.ADD_AI_STYLE,
    slug: string
  }

  // t.me/contact/<token> and tg://contact?token=<token> — the one-time link "My QR code" shows
  // (`contacts.exportContactToken`): whoever opens it gets its owner as a contact
  export interface InternalLinkContactToken {
    _: INTERNAL_LINK_TYPE.CONTACT_TOKEN,
    token: string,
    free?: string // a code that removes the owner's message fee for the one who follows the link
  }
}

export type InternalLinkTypeMap = {
  [INTERNAL_LINK_TYPE.MESSAGE]: InternalLink.InternalLinkMessage,
  [INTERNAL_LINK_TYPE.PRIVATE_POST]: InternalLink.InternalLinkPrivatePost,
  [INTERNAL_LINK_TYPE.STICKER_SET]: InternalLink.InternalLinkStickerSet,
  [INTERNAL_LINK_TYPE.JOIN_CHAT]: InternalLink.InternalLinkJoinChat,
  [INTERNAL_LINK_TYPE.VOICE_CHAT]: InternalLink.InternalLinkVoiceChat,
  [INTERNAL_LINK_TYPE.USER_PHONE_NUMBER]: InternalLink.InternalLinkUserPhoneNumber,
  [INTERNAL_LINK_TYPE.INVOICE]: InternalLink.InternalLinkInvoice,
  [INTERNAL_LINK_TYPE.EMOJI_SET]: InternalLink.InternalLinkEmojiSet,
  [INTERNAL_LINK_TYPE.ATTACH_MENU_BOT]: InternalLink.InternalLinkAttachMenuBot,
  [INTERNAL_LINK_TYPE.WEB_APP]: InternalLink.InternalLinkWebApp,
  [INTERNAL_LINK_TYPE.ADD_LIST]: InternalLink.InternalLinkAddList,
  [INTERNAL_LINK_TYPE.STORY]: InternalLink.InternalLinkStory,
  [INTERNAL_LINK_TYPE.BOOST]: InternalLink.InternalLinkBoost,
  [INTERNAL_LINK_TYPE.PREMIUM_FEATURES]: InternalLink.InternalLinkPremiumFeatures,
  [INTERNAL_LINK_TYPE.GIFT_CODE]: InternalLink.InternalLinkGiftCode,
  [INTERNAL_LINK_TYPE.BUSINESS_CHAT]: InternalLink.InternalLinkBusinessChat,
  [INTERNAL_LINK_TYPE.STARS_TOPUP]: InternalLink.InternalLinkStarsTopup,
  [INTERNAL_LINK_TYPE.SHARE]: InternalLink.InternalLinkShare,
  [INTERNAL_LINK_TYPE.UNIQUE_STAR_GIFT]: InternalLink.InternalLinkUniqueStarGift,
  [INTERNAL_LINK_TYPE.STAR_GIFT_COLLECTION]: InternalLink.InternalLinkStarGiftCollection,
  [INTERNAL_LINK_TYPE.STORY_ALBUM]: InternalLink.InternalLinkStoryAlbum,
  [INTERNAL_LINK_TYPE.INSTANT_VIEW]: InternalLink.InternalLinkInstantView,
  [INTERNAL_LINK_TYPE.NEW]: InternalLink.InternalLinkNew,
  [INTERNAL_LINK_TYPE.SETTINGS]: InternalLink.InternalLinkSettings,
  [INTERNAL_LINK_TYPE.CONTACTS]: InternalLink.InternalLinkContacts,
  [INTERNAL_LINK_TYPE.CHATS]: InternalLink.InternalLinkChats,
  [INTERNAL_LINK_TYPE.CONFERENCE_CALL]: InternalLink.InternalLinkConferenceCall,
  [INTERNAL_LINK_TYPE.ADD_AI_STYLE]: InternalLink.InternalLinkAddAiStyle,
  [INTERNAL_LINK_TYPE.CONTACT_TOKEN]: InternalLink.InternalLinkContactToken,
  [INTERNAL_LINK_TYPE.WALLET_SEND]: InternalLink.InternalLinkWalletSend,
  [INTERNAL_LINK_TYPE.TON_CONNECT]: InternalLink.InternalLinkTonConnect,
};
